const revokeSession = `-- name: RevokeSession :one
WITH target AS MATERIALIZED (
    SELECT session_id, state, version, user_id
    FROM backend.sessions
    WHERE session_id = $1::TEXT
    FOR UPDATE
), revoked AS (
    UPDATE backend.sessions AS sessions
    SET
        state = 'revoked',
        version = sessions.version + 1
    FROM target
    WHERE sessions.session_id = target.session_id
      AND target.state <> 'revoked'
    RETURNING sessions.session_id, sessions.state, sessions.version, sessions.user_id, target.state AS previous_state
)
SELECT session_id, state, version, user_id, previous_state, TRUE AS transitioned
FROM revoked
UNION ALL
SELECT session_id, state, version, user_id, state AS previous_state, FALSE AS transitioned
FROM target
WHERE state = 'revoked'
LIMIT 1
`

type RevokeSessionRow struct {
	SessionID     string       `db:"session_id" json:"session_id"`
	State         SessionState `db:"state" json:"state"`
	Version       int32        `db:"version" json:"version"`
	UserID        pgtype.Int4  `db:"user_id" json:"user_id"`
	PreviousState SessionState `db:"previous_state" json:"previous_state"`
	Transitioned  bool         `db:"transitioned" json:"transitioned"`
}

func (q *Queries) RevokeSession(ctx context.Context, sessionID string) (*RevokeSessionRow, error) {
	row := q.db.QueryRow(ctx, revokeSession, sessionID)
	var i RevokeSessionRow
	err := row.Scan(
		&i.SessionID,
		&i.State,
		&i.Version,
		&i.UserID,
		&i.PreviousState,
		&i.Transitioned,
	)
	return &i, err
}

const rotateSession = `-- name: RotateSession :one
WITH predecessor AS MATERIALIZED (
    SELECT session_id, state, version, user_id, expires_at
    FROM backend.sessions
    WHERE session_id = $1::TEXT
    FOR UPDATE
), revoked AS (
    UPDATE backend.sessions AS sessions
    SET
        state = 'revoked',
        version = sessions.version + 1
    FROM predecessor
    WHERE sessions.session_id = predecessor.session_id
      AND predecessor.state = 'authenticated'
      AND predecessor.version = $2::INT
      AND predecessor.user_id = $3::INT
      AND predecessor.expires_at >= NOW()
    RETURNING predecessor.user_id
), successor AS (
    INSERT INTO backend.sessions (
        session_id,
        state,
        user_id,
        data,
        expires_at
    )
    SELECT
        $4::TEXT,
        'authenticated'::backend.session_state,
        revoked.user_id,
        $5::BYTEA,
        NOW() + $6::INTERVAL
    FROM revoked
    RETURNING session_id, state, version, user_id, data, expires_at, challenge_kind, challenge_code, challenge_email, challenge_expires_at, failed_attempts
)
SELECT session_id, state, version, user_id, data, expires_at, challenge_kind, challenge_code, challenge_email, challenge_expires_at, failed_attempts FROM successor
`

type RotateSessionParams struct {
	OldSessionID    string        `db:"old_session_id" json:"old_session_id"`
	ExpectedVersion int32         `db:"expected_version" json:"expected_version"`
	ExpectedUserID  int32         `db:"expected_user_id" json:"expected_user_id"`
	NewSessionID    string        `db:"new_session_id" json:"new_session_id"`
	SuccessorData   []byte        `db:"successor_data" json:"successor_data"`
	SuccessorTtl    time.Duration `db:"successor_ttl" json:"successor_ttl"`
}

type RotateSessionRow struct {
	SessionID          string                   `db:"session_id" json:"session_id"`
	State              SessionState             `db:"state" json:"state"`
	Version            int32                    `db:"version" json:"version"`
	UserID             pgtype.Int4              `db:"user_id" json:"user_id"`
	Data               []byte                   `db:"data" json:"data"`
	ExpiresAt          pgtype.Timestamptz       `db:"expires_at" json:"expires_at"`
	ChallengeKind      NullSessionChallengeKind `db:"challenge_kind" json:"challenge_kind"`
	ChallengeCode      pgtype.Text              `db:"challenge_code" json:"challenge_code"`
	ChallengeEmail     pgtype.Text              `db:"challenge_email" json:"challenge_email"`
	ChallengeExpiresAt pgtype.Timestamptz       `db:"challenge_expires_at" json:"challenge_expires_at"`
	FailedAttempts     int32                    `db:"failed_attempts" json:"failed_attempts"`
}

func (q *Queries) RotateSession(ctx context.Context, arg *RotateSessionParams) (*RotateSessionRow, error) {
	row := q.db.QueryRow(ctx, rotateSession,
		arg.OldSessionID,
		arg.ExpectedVersion,
		arg.ExpectedUserID,
		arg.NewSessionID,
		arg.SuccessorData,
		arg.SuccessorTtl,
	)
	var i RotateSessionRow
	err := row.Scan(
		&i.SessionID,
		&i.State,
		&i.Version,
		&i.UserID,
		&i.Data,
		&i.ExpiresAt,
		&i.ChallengeKind,
		&i.ChallengeCode,
		&i.ChallengeEmail,
		&i.ChallengeExpiresAt,
		&i.FailedAttempts,
	)
	return &i, err
}

const updateSessionDataCAS = `-- name: UpdateSessionDataCAS :many
WITH input AS (
    SELECT
        unnest($1::TEXT[]) AS session_id,
        unnest($2::INT[]) AS expected_version,
        unnest($3::BYTEA[]) AS data
)
UPDATE backend.sessions AS sessions
SET
    data = input.data,
    version = sessions.version + 1
FROM input
WHERE sessions.session_id = input.session_id
  AND sessions.version = input.expected_version
  AND sessions.state IN ('pending', 'authenticated')
  AND sessions.expires_at >= NOW()
RETURNING sessions.session_id, sessions.version
`

type UpdateSessionDataCASParams struct {
	SessionIds       []string `db:"session_ids" json:"session_ids"`
	ExpectedVersions []int32  `db:"expected_versions" json:"expected_versions"`
	Payloads         [][]byte `db:"payloads" json:"payloads"`
}

type UpdateSessionDataCASRow struct {
	SessionID string `db:"session_id" json:"session_id"`
	Version   int32  `db:"version" json:"version"`
}

func (q *Queries) UpdateSessionDataCAS(ctx context.Context, arg *UpdateSessionDataCASParams) ([]*UpdateSessionDataCASRow, error) {
	rows, err := q.db.Query(ctx, updateSessionDataCAS, arg.SessionIds, arg.ExpectedVersions, arg.Payloads)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*UpdateSessionDataCASRow
	for rows.Next() {
		var i UpdateSessionDataCASRow
		if err := rows.Scan(&i.SessionID, &i.Version); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
